import torch


def gen_inputs(ctx, device):
    input_size = tuple(ctx["input_size"])
    output_size = list(ctx["output_size"])
    dtype = getattr(torch, ctx["grad_output__dtype"])
    x = torch.randn(input_size, dtype=dtype, device=device)
    scales_h = ctx["scales_h"]
    scales_w = ctx["scales_w"]
    if scales_h is None and scales_w is None:
        out = torch.ops.aten._upsample_nearest_exact2d(
            x, output_size, None, None
        )
    else:
        out = torch.ops.aten._upsample_nearest_exact2d(
            x, None, [float(scales_h), float(scales_w)]
        )
    return {"grad_output": torch.ones_like(out)}


def run(grad_output, output_size, input_size, scales_h, scales_w):
    return torch.ops.aten._upsample_nearest_exact2d_backward.default(
        grad_output, output_size, input_size, scales_h, scales_w
    )
